cd /app && if [ -z "$(find /tmp/secrets_tar -name secret_file.txt -print -quit 2>/dev/null)" ]; then python3 - <<'PY'
import os, sys, subprocess, importlib.util
out='/tmp/secrets_py'
os.makedirs(out, exist_ok=True)
if importlib.util.find_spec('py7zr') is None:
    try:
        subprocess.check_call([sys.executable, '-m', 'pip', 'install', '-q', 'py7zr'])
    except Exception as e:
        print('pip_install_failed', e)
        sys.exit(0)
import py7zr
try:
    with py7zr.SevenZipFile('/app/secrets.7z', 'r') as z:
        z.extractall(out)
    print('py_extract_ok')
except Exception as e:
    print('py_extract_failed', e)
for root, _, files in os.walk(out):
    for f in files:
        print(os.path.join(root, f))
PY
